##### C++

```cpp
#include <vector>
#include <algorithm>
#include <climits>
using namespace std;

vector<int> advantageBrute(const vector<int>& s) {
    int n = (int)s.size();
    vector<int> out(n);
    for (int i = 0; i < n; ++i) {
        int best = INT_MIN;
        for (int j = 0; j < n; ++j) if (j != i) best = max(best, s[j]);
        out[i] = s[i] - best;
    }
    return out;
}
```
