**The cycle (juggling) method.** A rotation is a **permutation** of the positions: the value at $i$ must go to $p(i) = (i + k) \bmod n$. Follow it: pick up the value at position $s$, drop it at $p(s)$, pick up what was there, drop it at $p(p(s))$, and so on until you return to $s$. Every value moves *exactly once*, with one spare variable. How many cycles are there? From $s$ we visit $s, s + k, s + 2k, \dots \pmod n$ and are back at $s$ after $t$ steps exactly when $n$ divides $tk$, that is after $t = n / \gcd(n, k)$ steps. So there are $g = \gcd(n, k)$ cycles of length $n / g$, and the cycle of $s$ contains exactly the positions congruent to $s$ modulo $g$; the starts $0, 1, \dots, g - 1$ cover every position once (@fig-arr-cycles).

::: {#arr-rotate-cycles .cell execution_count=45}
``` {.python .cell-code}
def rotate_right_cycles(a: list[int], k: int) -> list[int]:
    a = list(a)
    n = len(a)
    if n == 0 or k % n == 0:
        return a
    k %= n
    for s in range(math.gcd(n, k)):          # one start per cycle
        cur, carry = s, a[s]
        while True:
            cur = (cur + k) % n
            a[cur], carry = carry, a[cur]    # drop the carried value, pick up the next one
            if cur == s:
                break
    return a


def cycles_of(n: int, k: int) -> list[list[int]]:
    seen, out = set(), []
    for s in range(n):
        if s not in seen:
            cyc, cur = [], s
            while cur not in seen:
                seen.add(cur)
                cyc.append(cur)
                cur = (cur + k) % n
            out.append(cyc)
    return out


assert rotate_right_cycles([1, 2, 3, 4, 5, 6], 2) == [5, 6, 1, 2, 3, 4]
assert cycles_of(6, 2) == [[0, 2, 4], [1, 3, 5]] and len(cycles_of(7, 3)) == 1
for _ in range(1000):
    cy_n, cy_k = random.randint(1, 12), random.randint(0, 30)
    cy_a = list(range(cy_n))
    cy_r = cy_k % cy_n
    assert rotate_right_cycles(cy_a, cy_k) == cy_a[cy_n - cy_r:] + cy_a[:cy_n - cy_r]
    assert len(cycles_of(cy_n, cy_k)) == math.gcd(cy_n, cy_k)      # gcd(n, 0) = n one-cell cycles
```
