``` {.python .cell-code}
def ex26_rotate_left(a, k):
    a, n = list(a), len(a)
    k %= n
    reverse_range(a, 0, k)
    reverse_range(a, k, n)
    reverse_range(a, 0, n)
    return a

assert ex26_rotate_left([1, 2, 3], 1) == [2, 3, 1]
for _ in range(500):
